"""Generate D:/tgcalls/cmake/tgcalls/sources.cmake from tdesktop's Telegram/cmake/lib_tgcalls.cmake (v7.3.1).

Windows rules applied like tdesktop: paths with darwin/ mac/ osx/ are header-only on WIN32 (nice_target_sources),
platform/android/* and reference/* are removed (remove_target_sources). Only .cpp/.cc are listed (headers dropped).
Usage: python -I gen_tgcalls_cmake.py <lib_tgcalls.cmake> <tgcalls repo root> <out sources.cmake>
"""
import os
import re
import sys

cm, root, out = sys.argv[1], sys.argv[2], sys.argv[3]
text = open(cm, encoding='utf-8').read()
entries = []
for m in re.finditer(r"nice_target_sources\(lib_tgcalls \$\{tgcalls_loc\}\s*PRIVATE(.*?)\n\)", text, re.S):
    entries += [l.split('#')[0].strip() for l in m.group(1).splitlines()]
entries = [e for e in entries if e]
# the unconditional (column-0) remove block; the indented one sits inside if (APPLE)
rm = re.search(r"^remove_target_sources\(lib_tgcalls \$\{tgcalls_loc\}(.*?)\n\)", text, re.S | re.M)
removed = {l.strip() for l in rm.group(1).splitlines() if l.strip()}

srcs = []
for e in entries:
    if not e.endswith(('.cpp', '.cc')):
        continue
    if e in removed or any(t in e for t in ('darwin/', 'mac/', 'osx/')):
        continue
    if not os.path.isfile(os.path.join(root, 'tgcalls', e)):
        sys.exit('missing: ' + e)
    srcs.append(e)

with open(out, 'w', encoding='utf-8', newline='\n') as f:
    f.write('# Generated by gen_tgcalls_cmake.py from tdesktop v7.3.1 Telegram/cmake/lib_tgcalls.cmake (%d TUs on Windows)\n' % len(srcs))
    f.write('set(tgcalls_sources\n')
    for s in srcs:
        f.write('    ${tgcalls_loc}/%s\n' % s)
    f.write(')\n')
print(len(entries), 'entries,', len(srcs), 'compiled TUs')
